package com.example.lending;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Test
    void book_is_found_by_partial_title_ignoring_case() throws Exception {
        String marker = "Find" + UUID.randomUUID().toString().substring(0, 8);
        registerBook("Spring in Action " + marker);

        mockMvc.perform(get("/books").param("title", "spring in ACTION " + marker))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].title").value("Spring in Action " + marker))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"))
                .andExpect(jsonPath("$[0].id").isNotEmpty());

        mockMvc.perform(get("/books").param("title", marker.toUpperCase()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1));
    }

    @Test
    void every_book_whose_title_contains_keyword_is_returned() throws Exception {
        String keyword = "Kw" + UUID.randomUUID().toString().substring(0, 8);
        registerBook("Alpha " + keyword);
        registerBook(keyword + " Beta");
        registerBook("Gamma " + keyword.toLowerCase() + " Delta");
        registerBook("Unrelated title");

        mockMvc.perform(get("/books").param("title", keyword))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(3));
    }

    @Test
    void keyword_with_wildcard_characters_is_matched_literally() throws Exception {
        String marker = "Lit" + UUID.randomUUID().toString().substring(0, 8);
        registerBook("100% " + marker);
        registerBook("1000 " + marker);

        mockMvc.perform(get("/books").param("title", "100% " + marker))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("100% " + marker));
    }

    @Test
    void no_match_returns_empty_list() throws Exception {
        mockMvc.perform(get("/books").param("title", "no-such-book-" + UUID.randomUUID()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void blank_or_missing_title_returns_400() throws Exception {
        mockMvc.perform(get("/books").param("title", "   "))
                .andExpect(status().isBadRequest());

        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
    }

    private void registerBook(String title) throws Exception {
        mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated());
    }
}
